[Form]
public class TFMProcessOverview extends FormRun
{
    TFMProcess process;
    TFMProcessOverviewFormClass formClass;
    FormGroupControl            pagesUsingProcessGroup;
    TFMPage                     refPage;

}

public void saveNewProcess(TFMProcessID _processID, str _description, boolean _revertToClassic = false)
{
    formClass.saveProcess(_processID, _description, _revertToClassic);
    TFMProcessTable_DS.executeQuery();

}

public void run()
{
    formClass = new TFMProcessOverviewFormClass();
    super();
    TFMProcessTable_DS.executeQuery();
}

public void init()
{
    super();
    TFMProcessVersionDS.setTmp();
    DetailsHeader_OriginClass.visible(TFMParameters::IsInDeveloperMode());
}

public void setButtonMode(boolean _editMode)
{
    // Not in edit mode - Then show the buttons
    NewButton.visible(!_editMode);
    TFMDrawFlowButton_view.visible(!_editMode);

    // edit mode then show the Edit flow and lock version button.
    TFMDrawFlowButton_edit.visible(_editMode);
    LockVersionButton.visible(_editMode);

    // update the line
    TFMProcessVersion_AutoSave.enabled(_editMode);
    TFMProcessVersion_CancelBehaviour.enabled(_editMode);

}

public void updatePagesPane(AsyncTaskResult _result)
{
    TFMProcessID processId = TFMProcessVersionDS.ProcessID;
    if (!pagesUsingProcessGroup || processId != TFMProcessTable.ProcessID)
    {
        return;
    }

    Set pages = TFMPagesProvider::getAllPages().getPagesUsingProcess(processId);

    while (pagesUsingProcessGroup.controlCount())
    {
        pagesUsingProcessGroup.formRun().design().removeControl(pagesUsingProcessGroup.controlNum(1).id());
    }

    if (pagesUsingProcessGroup)
    {
        SetEnumerator sEnum = pages.getEnumerator();
        while (sEnum.moveNext())
        {
            TFMPage uirpage = sEnum.current();
            FormGroupControl fgc = pagesUsingProcessGroup.addControl(FormControlType::Group, uirpage.parmId()+'group');
            fgc.columns(2);
            TFMHtmlViewerCtrl       icon = fgc.addControlEx(classStr(TFMHtmlViewerCtrl), uirpage.parmId()+'icon');


            TFMGraphicsHelper::setImageHtmlWithWidth(uirpage.parmIcon(), icon, 25); 
            FormButtonControl   pageName = fgc.addControl(FormControlType::Button, uirpage.parmId());
            pageName.text(TFMListVisualization::getMenuTitle(uirpage.parmTitle()));

            pageName.heightValue(pagename.heightValue()*2);
            pageName.registerOverrideMethod(methodstr(FormButtonControl, clicked), formmethodStr(TFMProcessOverview, buttonClicked), this);

        }
    }
}

public void buttonClicked(FormButtonControl _control)
{
    MenuFunction mf = new MenuFunction(menuItemDisplayStr(TFMPageConfigurator), MenuItemType::Display);
    refPage = TFMPagesProvider::getAllPages().getPage(_control.name());
    mf.run(new Args(this));
}

public TFMPage getCurrentPage()
{
    return refPage;
}

public void setContextGroup(FormGroupControl _fgc)
{
    DrawFlow.setContextGroup(_fgc);
}

public void setPagesUsingProcessGroup(FormGroupControl _fgc)
{
    pagesUsingProcessGroup = _fgc;
}

public void updateEditModeOnCtrls()
{
    element.setButtonMode(process && !process.parmLocked() && process.parmDeltaLevel() != TFMDeltaLevel::Code);

    TFMProcessVersion newestVersion = TFMProcessVersion::newestProcessVersion(process.parmProcessName(), false);
    NewButton.visible(!newestVersion || newestVersion.Locked);
    LockVersionButton.visible(newestVersion && !newestVersion.Locked && process.parmVersion() == newestVersion.Version);

    DrawFlow.setEditorModeOnControl(!TFMDrawFlowButton_edit.visible());
}

/// <summary>
/// Shows the loader. Runs Async unless the parameter is set to false. Then it will showed with a higher priority.
/// </summary>
/// <param name = "_runAsync"></param>
public void showLoader(boolean _runAsync = true)
{
    if(_runAsync)
    {
        System.Threading.CancellationTokenSource cancellationTokenForUpdateVisual = new System.Threading.CancellationTokenSource();
        element.setTimeoutEx(formMethodStr(TFMProcessOverview,updateVisualAsync),conNull(),1, cancellationTokenForUpdateVisual.Token);
    } 
    else
    {
        element.updateVisualAsync(null);
    }
}

public void executeQueryForVersion()
{
    TFMProcessVersionDS_ds.executeQuery();
}

public void updateVisualAsync(AsyncTaskResult _result)
{
    DrawFlow.sendUpdatingToControl();
}

public void setActiveProcessAsync(AsyncTaskResult _result)
{
    if(!TFMProcessTable.ProcessID)
    {
        return;
    }

    process = TFMProcessProvider::GetAllProcessesImpl().getProcessInfo(TFMProcessTable.ProcessID);
    formClass.setCurrentProcess(process);
    boolean found = true;

    TFMDocumentTypeAttribute documentTypeAttr = new TFMDocumentTypeAttribute(classStr(TFMPostAdhocRegistration), TFMProcessTable.ProcessID);
    Object classObj = TFMGetRegistrationConfiguration::getClassFromSysAttribute(classStr(TFMDocumentHandler), documentTypeAttr);
    DetailsHeader_RevertToClassic.visible(classObj != null);

    TFMProcessVersionDS_ds.executeQuery();
}

public void setActiveVersionAsync(AsyncTaskResult _result)
{
    if(!TFMProcessTable.ProcessID || TFMProcessTable.ProcessID != TFMProcessVersionDS.ProcessID )
    {
        return ;
    }

    process = TFMProcessProvider::GetAllProcessesImpl().getProcess(TFMProcessTable.ProcessID, TFMProcessVersionDS.Version);
    TFMDrawFlowControlInteractionLogicBlocks interactionClass = DrawFlow.interactionClass();
    interactionClass.SetProcess(process);
    DrawFlow.updateControlData();
    element.updateEditModeOnCtrls();
}

public int active()
{

    if(DetailsHeader_ProcessId.valueStr())
    {
        element.showLoader();
    }

    System.Threading.CancellationTokenSource cancellationTokenForUpdateVisual = new System.Threading.CancellationTokenSource();
    element.setTimeoutEx(formMethodStr(TFMProcessOverview,setActiveProcessAsync),conNull(),50, cancellationTokenForUpdateVisual.Token);

    int ret;
    ret = super();

    return ret;
}

public void init()
{
    TFMPage                 page;
    QueryBuildRange         qbr;
    super();


    if (element.args().caller() && element.args().caller().name() == formStr(TFMPageOverview))
    {
        qbr = TFMProcessTable_ds.queryBuildDataSource().addRange(fieldnum(TFMProcessTable, ProcessID));
        page = element.args().caller().getCurrentPage();
        qbr.value(page.parmId());
    }
}

public void executeQuery()
{
    TFMProcessTable.setTmp();
    TFMProcessTable.setTmpData(TFMProcessProvider::GetAllProcessesImpl().getTempProcessTable());
    super();
}

public void write()
{
    super();
    formClass.saveProcess(TFMProcessTable.ProcessID, TFMProcessTable.Description, TFMProcessTable.RevertToClassic);
}

/// <summary>
/// Since form uses a TmpVersion of the process table the process needs to be deleted from the real db table.
/// </summary>
public void delete()
{
    TFMProcessID processId = TFMProcessTable.ProcessID;

    if(process.parmDeltaLevel() != TFMDeltaLevel::Code)
    {
        if (Box::okCancel("@TFM:AreyousureyouwanttodeletetheProc",DialogButton::Cancel) != DialogButton::Ok)
        {
            return;
        }

        formClass.deleteProcessAndVersions(processId);

        TFMProcessTable_DS.executeQuery();
    }
    else
    {
        Box::stop("@TFM:Codeversionscannotbedeleted");
        return;
    }
}

public int active()
{
    int ret;
    element.showLoader();
    ret = super();

    System.Threading.CancellationTokenSource cancellationTokenForUpdateVisual = new System.Threading.CancellationTokenSource();
    element.setTimeoutEx(formMethodStr(TFMProcessOverview,setActiveVersionAsync),conNull(),10, cancellationTokenForUpdateVisual.Token);

    element.setTimeoutEx(formMethodStr(TFMProcessOverview,updatePagesPane),conNull(),500, cancellationTokenForUpdateVisual.Token);

    return ret;
}

public void executeQuery()
{
    TFMProcessVersion dbProcessVersion, finalProcessVersion;
    TFMProcessVersionDS.setTmp();
    finalProcessVersion.setTmp();
    if(!process)
    {
        return;
    }

    if(process.parmDeltaLevel() != TFMDeltaLevel::Custom)
    {
        finalProcessVersion.clear();
        finalProcessVersion.ProcessID = TFMProcessTable.ProcessID;
        finalProcessVersion.AutoSave = process.parmAutoSave();
        finalProcessVersion.CancelBehaviour = process.parmCancelBehaviour();
        finalProcessVersion.Locked = true;
        finalProcessVersion.Version = 0;
        finalProcessVersion.doInsert();
    }

    while select dbProcessVersion where dbProcessVersion.ProcessID == TFMProcessTable.ProcessID
    {
        finalProcessVersion.clear();
        finalProcessVersion.AutoSave = dbProcessVersion.AutoSave;
        finalProcessVersion.CancelBehaviour = dbProcessVersion.CancelBehaviour;
        finalProcessVersion.Locked = dbProcessVersion.Locked;
        finalProcessVersion.Version = dbProcessVersion.Version;
        finalProcessVersion.ProcessID = dbProcessVersion.ProcessID;
        finalProcessVersion.RecId = dbProcessVersion.RecId;
        finalProcessVersion.doInsert();
    }

    TFMProcessVersionDS.setTmpData(finalProcessVersion);
    super();
}

/// <summary>
///
/// </summary>
public void write()
{
    super();
    if(TFMProcessVersionDS.Version && !TFMProcessVersionDS.Locked)
    {
        formClass.saveProcessVersion(TFMProcessVersionDS.ProcessID, TFMProcessVersionDS.Version, TFMProcessVersionDS.CancelBehaviour, TFMProcessVersionDS.AutoSave);
    }
}

/// <summary>
///
/// </summary>
public void clicked()
{
    super();
    TFMProcessProvider::instance().invalidateProvider();

    int pos = TFMProcessTable_ds.getPosition();
    TFMProcessTable_ds.executeQuery();
    TFMProcessTable_ds.setPosition(pos);
}

/// <summary>
///
/// </summary>
public void lookup()
{
    //super();
    TFMFormLookupHelper::lookupClassesExtendingCertainClass(this, classStr(TFMProcess), "@TFM:Description");
}

public void clicked()
{
    super();
    TFMProcessVersion::Increment(TFMProcessTable.ProcessID);
    TFMProcessProvider::instance().invalidateProvider();

    int pos = TFMProcessTable_ds.getPosition();
    TFMProcessTable_ds.executeQuery();
    TFMProcessTable_ds.setPosition(pos);

    pos = TFMProcessVersionDS_ds.getPosition();
    TFMProcessVersionDS_ds.executeQuery();
    TFMProcessVersionDS_ds.setPosition(pos);

}

public void clicked()
{
    super();
    TFMProcessVersion::lockVersion(TFMProcessTable.ProcessID);
    TFMProcessProvider::instance().invalidateProvider();

    int pos = TFMProcessTable_ds.getPosition();
    TFMProcessTable_ds.executeQuery();
    TFMProcessTable_ds.setPosition(pos);

    pos = TFMProcessVersionDS_ds.getPosition();
    TFMProcessVersionDS_ds.executeQuery();
    TFMProcessVersionDS_ds.setPosition(pos);
}
